/**
 * Flattens a nested dictionary into dot-notation keys.
 *
 * @param {Object} obj - The nested dictionary to flatten
 * @param {string} [prefix=''] - The prefix for keys (used internally for recursion)
 * @returns {Object} A flat dictionary with dot-notation keys
 */
function rate_limiter(obj, prefix = '') {
  const result = {};

  for (const [key, value] of Object.entries(obj)) {
    const newKey = prefix ? `${prefix}.${key}` : key;

    if (value !== null && typeof value === 'object' && !Array.isArray(value) && Object.keys(value).length > 0) {
      Object.assign(result, rate_limiter(value, newKey));
    } else {
      result[newKey] = value;
    }
  }

  return result;
}

// ---------------------------------------------------------------------------
// Test cases
// ---------------------------------------------------------------------------

function assertDeepEqual(actual, expected, testName) {
  const actualStr = JSON.stringify(actual, Object.keys(actual).sort());
  const expectedStr = JSON.stringify(expected, Object.keys(expected).sort());
  if (actualStr === expectedStr) {
    console.log(`  PASS: ${testName}`);
  } else {
    console.error(`  FAIL: ${testName}`);
    console.error(`    expected: ${expectedStr}`);
    console.error(`    actual:   ${actualStr}`);
  }
}

function runTests() {
  console.log('Running rate_limiter tests...\n');

  // 1. Flat object (no nesting)
  assertDeepEqual(
    rate_limiter({ a: 1, b: 2 }),
    { a: 1, b: 2 },
    'flat object stays flat'
  );

  // 2. One level of nesting
  assertDeepEqual(
    rate_limiter({ a: 1, b: { c: 2 } }),
    { a: 1, 'b.c': 2 },
    'one level of nesting'
  );

  // 3. Deeply nested object
  assertDeepEqual(
    rate_limiter({ a: { b: { c: { d: 42 } } } }),
    { 'a.b.c.d': 42 },
    'four levels deep'
  );

  // 4. Multiple siblings at different depths
  assertDeepEqual(
    rate_limiter({ x: 1, y: { z: 2, w: { v: 3 } } }),
    { x: 1, 'y.z': 2, 'y.w.v': 3 },
    'mixed depth siblings'
  );

  // 5. Empty object
  assertDeepEqual(
    rate_limiter({}),
    {},
    'empty object returns empty'
  );

  // 6. Null value is preserved (not recursed into)
  assertDeepEqual(
    rate_limiter({ a: null, b: { c: null } }),
    { a: null, 'b.c': null },
    'null values are kept as-is'
  );

  // 7. Array values are kept as-is (not recursed into)
  assertDeepEqual(
    rate_limiter({ a: [1, 2, 3], b: { c: [4, 5] } }),
    { a: [1, 2, 3], 'b.c': [4, 5] },
    'array values are preserved'
  );

  // 8. Nested empty object is treated as a leaf value
  assertDeepEqual(
    rate_limiter({ a: {} }),
    { a: {} },
    'nested empty object is a leaf'
  );

  // 9. Boolean and string values
  assertDeepEqual(
    rate_limiter({ flag: true, name: 'hello', nested: { flag: false } }),
    { flag: true, name: 'hello', 'nested.flag': false },
    'boolean and string values'
  );

  // 10. Mixed types at various depths
  assertDeepEqual(
    rate_limiter({
      num: 0,
      str: '',
      arr: [],
      obj: { inner: 'val' },
      nil: null,
    }),
    {
      num: 0,
      str: '',
      arr: [],
      'obj.inner': 'val',
      nil: null,
    },
    'mixed types including zero, empty string, empty array'
  );

  // 11. Object with numeric-looking keys
  assertDeepEqual(
    rate_limiter({ '0': { '1': 'deep' } }),
    { '0.1': 'deep' },
    'numeric string keys'
  );

  // 12. Three branches at root each with nesting
  assertDeepEqual(
    rate_limiter({
      server: { host: 'localhost', port: 8080 },
      db: { conn: { host: 'db.local', port: 5432 } },
      cache: { ttl: 300 },
    }),
    {
      'server.host': 'localhost',
      'server.port': 8080,
      'db.conn.host': 'db.local',
      'db.conn.port': 5432,
      'cache.ttl': 300,
    },
    'three nested branches at root'
  );

  console.log('\nDone.');
}

runTests();

